from lib import *
S = SS('h16')
steps = [
    step("我在本机写了一个四层(TCP)负载均衡器:每接受一条新连接就按轮流顺序选一个后端,之后只搬运字节、看不懂 HTTP/2——相当于 Kubernetes 的 ClusterIP 之类“按连接均衡”的东西。2 个后端、6 个客户端各发 100 次:各后端收到 [300 300],均衡器接受了 6 条连接。加入第 3 个后端,原来的 6 个客户端再各发 100 次:[300 300 0],均衡器接受的连接仍是 6 条——新后端一个请求都没有,因为已有的连接不会被重新分配。再新建 3 个客户端各发 100 次:[100 100 100],连接数变成 9 条——只有新建的连接才会被分到新后端。", t=tl(S(1)), done=lidx(S(1), '再新建 3 个客户端'), mark=lidx(S(1), '加入第 3 个后端后'), b=bars([['加入第 3 个后端后,新后端收到', 0, '0'], ['新建 3 个客户端后,新后端收到', 100, '100']], 110, mark=[0], done=[1]), kv=KV([['已有连接', '不迁移:[300 300 0]'], ['均衡器接受的连接', '仍是 6 条'], ['新建连接', '才会分到新后端:[100 100 100]']], ['已有连接'])),
    step("请求量不均的客户端:4 个客户端经同一个四层均衡器连 2 个后端,调用次数分别是 1000、100、100、100。连接是平均分的(每个后端 2 条),但请求不平均:各后端收到 [1100 200],后端 0 占 85%。四层均衡器均衡的是“连接数”,不是请求数;一条连接上的请求量由客户端决定。", t=tl(S(2)), done=lidx(S(2), '各后端收到'), mark=lidx(S(2), '各后端收到'), b=bars([['后端 0 收到', 1100, '1100'], ['后端 1 收到', 200, '200']], 1150, mark=[0], done=[1]), kv=KV([['连接', '每个后端 2 条,平均'], ['请求', '[1100 200],后端 0 占 85%'], ['原因', '最忙的客户端那条连接落在后端 0']], ['原因'])),
    step("换成客户端自己做 round_robin(直接拿到 3 个后端的地址,每个请求都在 3 个后端之间轮流):同样 1000+100+100+100 次调用,各后端收到 [421 420 421]。客户端负载均衡是按请求分的,不管某个客户端有多忙;代价是客户端要自己知道所有后端的地址(第 15 篇)。", t=tl(S(3)), done=lidx(S(3), '1000+100+100+100'), mark=lidx(S(3), '1000+100+100+100'), b=bars([['后端 0 收到', 421, '421'], ['后端 1 收到', 420, '420'], ['后端 2 收到', 421, '421']], 450, done=[0, 1, 2]), kv=KV([['round_robin(按请求)', '[421 420 421]'], ['四层均衡(按连接)', '[1100 200](2 个后端)'], ['代价', '客户端要拿到全部后端地址']], ['round_robin(按请求)'])),
    step("让服务端定期结束长连接:后端设 MaxConnectionAge = 1 秒、宽限 1 秒,仍经四层均衡器;6 个客户端每 20 ms 调用一次;第 2 秒加入第 3 个后端。每秒各后端收到的次数:第 1 秒 [135 135]、第 2 秒 [133 131 0](新后端已加入但还没人用)、第 3 秒 [100 94 82]、第 4 秒 [87 88 89],之后一直是三个后端各约 90。整个过程失败的调用 0 个,均衡器共接受 49 条连接(不设年龄时只有 6 条)。服务端到期会先发 GOAWAY、给在途的调用宽限时间,客户端随后建立新连接,新连接又被均衡器重新分配;把它设成分钟级的值,就是“长连接均衡”的常用办法(第 40 篇)。", t=tl(S(4)), done=lidx(S(4), '整个过程中失败的调用'), mark=lidx(S(4), '第 3 秒内'), b=bars([['第 2 秒新后端收到', 0, '0'], ['第 3 秒新后端收到', 82, '82'], ['第 4 秒新后端收到', 89, '89']], 100, mark=[0], done=[1, 2]), kv=KV([['MaxConnectionAge = 1 s', '连接定期重建'], ['新后端', '1~2 秒内追平,约各 90 次/秒'], ['失败的调用', '0 个']], ['新后端'])),
]
A = mkarth('h16', 16, 'gRPC,负载均衡,长连接,四层均衡,MaxConnectionAge,不均衡,Go,真实验证,动画演示',
    '实测 gRPC 长连接的负载不均:按连接分配的四层均衡器在新增后端后,已有的连接不会迁移,新后端一个请求都没有;客户端请求量不同会让后端负载悬殊;客户端自己 round_robin 与服务端 MaxConnectionAge 各自怎么解决。',
    'gRPC 的一条 HTTP/2 连接可以复用很久。当连接在均衡器后面建立之后,新增的后端会不会分到流量?请求量不同的客户端会怎样?这篇用一个自己写的四层均衡器逐项验证。',
    [('[300 300 0]', '加入第 3 个后端后,已有的 6 个客户端再发 600 次请求,新后端收到的次数'), ('[1100 200]', '4 个客户端(1000/100/100/100 次)经按连接均衡的均衡器分到 2 个后端的请求数'), ('0 个失败 / 49 条连接', 'MaxConnectionAge = 1 s 时,连接定期重建、均衡自动恢复,整个过程的失败数与连接数')],
    [('为什么会不均衡', '<p>HTTP/2 在一条连接上复用很多请求。四层均衡器只在建立连接时选后端,之后这条连接上所有请求都去同一个后端;新增后端后,只有新建的连接才会分到它,已有的连接继续待在原后端——扩容之后新后端闲着就是典型表现。</p>'),
     ('请求量差异', '<p>按连接均衡并不等于按请求均衡:一条连接上跑多少请求由客户端决定,忙的客户端把它所在的后端压垮,而别的后端很闲。</p>'),
     ('客户端负载均衡', '<p>客户端拿到全部后端地址、自己做 round_robin,则每个请求轮流发给各后端,与客户端忙闲无关。要求客户端能拿到地址列表并及时更新(第 15 篇)。</p>'),
     ('MaxConnectionAge', '<p>服务端让连接活一段时间就发 GOAWAY 并关闭(带宽限期),客户端重新连接,均衡器重新分配。设置过短会增加建连开销,过长则恢复均衡慢;读源码时看到服务端给这个值加了 ±10% 的随机抖动,避免所有连接同时断开。</p>')],
    steps,
    [ENV_H + '。“四层均衡器”是我写的简易 TCP 转发(按连接轮流选后端,不解析 HTTP/2),只模拟“按连接分配”这一类行为,并不代表某个具体产品;第四节每个后端的 MaxConnectionAge 都是 1 秒,是为了在实验里很快看到效果,生产环境通常用分钟级;MaxConnectionAge 的 ±10% 抖动读自 http2_server.go',
     '没有验证:真实的 Kubernetes ClusterIP / kube-proxy / 云厂商四层均衡器的行为(不同产品是否按连接、是否有连接复用);七层(HTTP/2 感知)均衡器按请求分配的行为;least_request 等策略;MaxConnectionAge 过短时的建连开销(第 40 篇);客户端 round_robin 时地址列表更新的及时性(第 15 篇测过 DNS)'],
    '长连接均衡')
